{"python_code":"def build(p, frame):
    axis = App.Vector(1, 0, 0)

    def cylinder(radius, start, end):
        return Part.makeCylinder(radius, end - start,
                                 App.Vector(start, 0, 0), axis)

    def union(shapes):
        result = shapes[0]
        for shape in shapes[1:]:
            result = result.fuse(shape)
        return result.removeSplitter()

    def finish(shape, name):
        shape = shape.removeSplitter()
        if shape.isNull() or not shape.isValid() or len(shape.Solids) != 1:
            raise ValueError(name + ' must be a valid single solid')
        shape.Placement = frame.multiply(shape.Placement)
        return shape

    bearing_outer = cylinder(p['outer_radius'], p['shoulder'],
                             p['bearing_end'])
    bearing_void = union([
        cylinder(p['rear_bore'], p['shoulder'], p['relief_start']),
        cylinder(p['relief_radius'], p['relief_start'], p['relief_end']),
        cylinder(p['front_bore'], p['relief_end'], p['bearing_end'])
    ])
    bearing = bearing_outer.cut(bearing_void)

    x0 = p['x0']
    sleeve_end = x0 + p['sleeve_length']
    sleeve_outer = union([
        cylinder(p['sleeve_radius'], x0, sleeve_end),
        cylinder(p['outer_radius'], x0, p['shoulder'])
    ])

    void_parts = [cylinder(p['sleeve_bore'], x0, sleeve_end)]
    count = p['groove_count']
    for i in range(count):
        groove = Part.makeBox(
            p['sleeve_length'], p['groove_root'], p['groove_width'],
            App.Vector(x0, 0, -p['groove_width'] / 2.0)
        )
        groove.rotate(App.Vector(x0, 0, 0), axis, 360.0 * i / count)
        void_parts.append(groove)
    sleeve = sleeve_outer.cut(union(void_parts))

    return {
        'bearing': finish(bearing, 'bearing'),
        'sleeve': finish(sleeve, 'sleeve')
    }
